  // build an equivalent reaction and dispose it the same way the store does.

  // 1. Prove the reaction fires before dispose.
  runInAction(() => { store.someObservable = 1; });
  await when(() => effect.mock.calls.length === 1);

  // 2. Dispose.
  store.dispose();

  // 3. Trigger the mutation that would normally fire it.
  runInAction(() => { store.someObservable = 2; });

  // 4. Give any (now-disposed) reaction a chance to run, then assert it didn't.
  await Promise.resolve();

  expect(effect).toHaveBeenCalledTimes(1); // still 1, not 2
});
```

